// Email deliverability checker - tune here.
const LOOKBACK_DAYS = 30;
return [{ json: {
  // Cutoff for the Microsoft Graph receivedAfter filter, derived from LOOKBACK_DAYS.
  SINCE_ISO: new Date(Date.now() - LOOKBACK_DAYS * 86400000).toISOString(),
  // The domain you send FROM (not your website domain, if they differ).
  DOMAIN: 'nocode.expert',

  // DKIM selectors to probe. Each ESP publishes its key under its own selector,
  // so probing this list also tells you which ESP a domain is set up for.
  // Unresolved selectors are not errors, they just mean "not that provider".
  DKIM_SELECTORS: [
    'resend',                      // Resend
    'google',                      // Google Workspace
    'k1', 'k2',                    // Klaviyo, SendGrid
    's1', 's2',                    // Amazon SES, Zoho
    'selector1', 'selector2',      // Microsoft 365
    'mail', 'dkim', 'default',     // common self-hosted
    'mandrill', 'pm', 'sm',        // Mailchimp Transactional, Postmark, SparkPost
  ],

  // Real-placement branches (optional): the address your CAMPAIGNS ARE SENT
  // FROM. Not your inbound or contact address. The connected mailboxes must be
  // subscribed to that mail directly. Forwarded mail bypasses part of the
  // provider's filtering and will read cleaner than reality.
  SENDER_ADDRESS: 'user@example.com',
  LOOKBACK_DAYS: LOOKBACK_DAYS,
  MAX_MESSAGES: 25,

  // SPF has a hard 10 DNS-lookup limit. Warn before it is hit.
  SPF_LOOKUP_WARN: 8,
} }];

// Build one DNS question per check. No API calls here, string building only.
const cfg = $('Set config: deliverability').first().json;
const d = cfg.DOMAIN.trim().toLowerCase().replace(/^https?:\/\//, '').replace(/\/.*$/, '');

const q = [];
q.push({ check: 'spf', label: 'SPF', name: d, type: 'TXT' });
q.push({ check: 'dmarc', label: 'DMARC', name: '_dmarc.' + d, type: 'TXT' });
q.push({ check: 'mx', label: 'MX', name: d, type: 'MX' });
(cfg.DKIM_SELECTORS || []).forEach((sel) => {
  q.push({ check: 'dkim', label: 'DKIM ' + sel, selector: sel, name: sel + '._domainkey.' + d, type: 'TXT' });
});

return q.map((x) => ({ json: Object.assign({ domain: d }, x) }));

// Pair each DoH answer back with the question that produced it. The HTTP node
// preserves input order, so index alignment is safe here.
const questions = $('Build DNS queries').all().map((i) => i.json);
return $input.all().map((item, idx) => {
  const q = questions[idx] || {};
  return { json: Object.assign({}, item.json, { _q: q, _q_name: q.name, domain: q.domain }) };
});

// Aggregate every DNS answer into a graded checklist. Pure transforms.
const cfg = $('Set config: deliverability').first().json;
const rows = $input.all().map((i) => i.json);
const domain = (rows[0] && rows[0].domain) || cfg.DOMAIN;

// Each item carries the DoH JSON plus the question it answered. Google's
// resolver returns { Status, Answer: [{ name, type, data }] }. Status 0 = ok,
// 3 = NXDOMAIN. Quoted TXT chunks are concatenated for long keys.
const answersFor = (row) => {
  const a = (row.Answer || []).map((x) => String(x.data || ''));
  return a.map((s) => s.replace(/^"|"$/g, '').replace(/" "/g, ''));
};

const byCheck = { spf: [], dmarc: [], mx: [], dkim: [] };
rows.forEach((r) => {
  const q = $('Build DNS queries').all().find((i) => i.json.name === r._q_name);
  const meta = r._q || {};
  if (byCheck[meta.check]) byCheck[meta.check].push({ meta: meta, answers: answersFor(r), status: r.Status });
});

const checks = [];
const add = (id, label, status, detail, move) => checks.push({ id: id, label: label, status: status, detail: detail, move: move || '' });

// ---- SPF ------------------------------------------------------------------
const spfRow = byCheck.spf[0];
const spfRecords = spfRow ? spfRow.answers.filter((t) => /^v=spf1/i.test(t)) : [];
if (!spfRecords.length) {
  add('SPF', 'SPF record', 'critical', 'No SPF record found on ' + domain + '.',
    'Publish a TXT record starting v=spf1 that lists every service allowed to send as this domain, ending in ~all.');
} else if (spfRecords.length > 1) {
  add('SPF', 'SPF record', 'critical', spfRecords.length + ' SPF records found. More than one is a permanent error and receivers will fail the check outright.',
    'Merge them into a single TXT record.');
} else {
  const spf = spfRecords[0];
  // Mechanisms that each cost a DNS lookup against the hard limit of 10.
  const lookups = (spf.match(/(^|\s)(include:|a[:\s]|mx[:\s]|ptr|exists:|redirect=)/gi) || []).length;
  const allMech = (spf.match(/[~\-+?]all/i) || [''])[0].toLowerCase();
  if (allMech === '+all') {
    add('SPF', 'SPF policy', 'critical', 'SPF ends in +all, which authorises the entire internet to send as you.', 'Change +all to ~all.');
  } else if (!allMech) {
    add('SPF', 'SPF policy', 'flag', 'SPF has no all mechanism, so receivers apply a neutral result.', 'End the record with ~all.');
  } else {
    add('SPF', 'SPF policy', 'pass', 'Ends in ' + allMech + '.', '');
  }
  if (lookups > 10) {
    add('SPF', 'SPF lookup count', 'critical', lookups + ' top-level DNS lookups, over the hard limit of 10. SPF returns permerror and every check fails.',
      'Flatten or remove includes. Note nested includes add more lookups on top of this count.');
  } else if (lookups >= cfg.SPF_LOOKUP_WARN) {
    add('SPF', 'SPF lookup count', 'flag', lookups + ' top-level DNS lookups against a limit of 10, and nested includes add more.',
      'Audit the includes before adding another sending service.');
  } else {
    add('SPF', 'SPF lookup count', 'pass', lookups + ' top-level lookups, within the limit of 10.', '');
  }
}

// ---- DMARC ----------------------------------------------------------------
const dmarcRow = byCheck.dmarc[0];
const dmarcRec = dmarcRow ? dmarcRow.answers.find((t) => /^v=DMARC1/i.test(t)) : null;
if (!dmarcRec) {
  add('DMARC', 'DMARC record', 'critical', 'No DMARC record on _dmarc.' + domain + '.',
    'Publish v=DMARC1; p=none; rua=mailto:you@' + domain + ' to start collecting reports, then tighten to quarantine.');
} else {
  const p = ((dmarcRec.match(/[;\s]p=([a-z]+)/i) || [])[1] || 'none').toLowerCase();
  const rua = /rua=/i.test(dmarcRec);
  const pct = (dmarcRec.match(/[;\s]pct=(\d+)/i) || [])[1];
  if (p === 'none') {
    add('DMARC', 'DMARC policy', 'flag', 'Policy is p=none, so DMARC is only monitoring. Nothing is actually protected and spoofed mail is still delivered.',
      'Move to p=quarantine once your reports are clean. Gmail and Yahoo require DMARC for bulk senders.');
  } else {
    add('DMARC', 'DMARC policy', 'pass', 'Policy is p=' + p + (pct ? ' at pct=' + pct : '') + '.', '');
  }
  add('DMARC', 'DMARC reporting', rua ? 'pass' : 'flag',
    rua ? 'Aggregate reports are being collected (rua present).' : 'No rua address, so you receive no aggregate reports and are blind to failures.',
    rua ? '' : 'Add rua=mailto:dmarc@' + domain + ' to the record.');
}

// ---- DKIM -----------------------------------------------------------------
const found = byCheck.dkim.filter((r) => r.answers.some((t) => /v=DKIM1/i.test(t) || /(^|;)\s*p=[A-Za-z0-9+/]/.test(t)));
const foundSelectors = found.map((r) => r.meta.selector);
if (!found.length) {
  add('DKIM', 'DKIM key', 'critical', 'No DKIM key found on any of the ' + byCheck.dkim.length + ' selectors probed.',
    'Your ESP publishes the selector to use. Unsigned mail fails DMARC alignment and gets filtered.');
} else {
  const empty = found.filter((r) => r.answers.some((t) => /(^|;)\s*p=\s*(;|$)/.test(t)));
  if (empty.length) {
    add('DKIM', 'DKIM key', 'critical', 'Selector ' + empty[0].meta.selector + ' exists but the public key is empty, which is how a revoked key looks.',
      'Re-publish the key from your ESP.');
  } else {
    add('DKIM', 'DKIM key', 'pass', 'Key found on: ' + foundSelectors.join(', ') + '.', '');
  }
}

// ---- MX -------------------------------------------------------------------
const mxRow = byCheck.mx[0];
const mxCount = mxRow ? mxRow.answers.length : 0;
add('MX', 'MX records', mxCount ? 'pass' : 'flag',
  mxCount ? mxCount + ' MX record(s) present.' : 'No MX records. You cannot receive replies, bounces, or DMARC reports at this domain.',
  mxCount ? '' : 'Add MX records, even if you only send. Receivers treat a send-only domain with no MX as suspicious.');

const criticals = checks.filter((c) => c.status === 'critical');
const flags = checks.filter((c) => c.status === 'flag');
const passes = checks.filter((c) => c.status === 'pass');
const verdict = criticals.length ? 'failing' : flags.length ? 'at risk' : 'clean';

return [{ json: {
  domain: domain,
  verdict: verdict,
  counts: { passed: passes.length, flags: flags.length, critical: criticals.length },
  checks: checks,
  dkim_selectors_found: foundSelectors,
  dkim_selectors_probed: byCheck.dkim.length,
  spf_record: spfRecords[0] || null,
  dmarc_record: dmarcRec || null,
} }];

// Branch B: real placement from Gmail's own system labels.
// Gmail exposes its tabs as labels, so CATEGORY_PROMOTIONS is the Promotions
// tab and SPAM is the spam folder. No seed network and no third party needed.
const msgs = $input.all().map((i) => i.json).filter((m) => m && m.id);

const tabOf = (L) => {
  L = L || [];
  if (L.indexOf('SPAM') !== -1) return 'Spam';
  if (L.indexOf('TRASH') !== -1) return 'Trash';
  if (L.indexOf('CATEGORY_PROMOTIONS') !== -1) return 'Promotions';
  if (L.indexOf('CATEGORY_UPDATES') !== -1) return 'Updates';
  if (L.indexOf('CATEGORY_SOCIAL') !== -1) return 'Social';
  if (L.indexOf('CATEGORY_FORUMS') !== -1) return 'Forums';
  if (L.indexOf('INBOX') !== -1) return 'Primary';
  return 'Unknown';
};

const tally = {};
const samples = [];
msgs.forEach((m) => {
  const tab = tabOf(m.labelIds);
  tally[tab] = (tally[tab] || 0) + 1;
  if (samples.length < 5) {
    const h = ((m.payload && m.payload.headers) || []).find((x) => x.name === 'Subject');
    samples.push({ tab: tab, subject: h ? h.value : '(no subject)' });
  }
});

const n = msgs.length;
const pctOf = (k) => (n ? Math.round((k / n) * 100) : null);
const inboxed = tally.Primary || 0;
const filtered = (tally.Promotions || 0) + (tally.Updates || 0) + (tally.Social || 0) + (tally.Forums || 0);
const spam = (tally.Spam || 0) + (tally.Trash || 0);

return [{ json: { _branch: 'gmail', placement: {
  provider: 'Gmail',
  inbox_label: 'Primary', filtered_label: 'Promotions/Updates',
  checked: n, tally: tally,
  inbox_pct: pctOf(inboxed), filtered_pct: pctOf(filtered), spam_pct: pctOf(spam),
  samples: samples, skipped: n === 0,
} } }];

// Branch C: real placement from Microsoft Graph.
// Two reads rather than one, because a Graph message carries parentFolderId but
// not the folder NAME. Querying the well-known folders separately means the
// folder is known from which node returned the message, with no ID lookup.
// Within the inbox, inferenceClassification is Outlook's Focused/Other split,
// which is the closest equivalent to Gmail's tabs.
const grab = (node) => {
  try { return $(node).all().map((i) => i.json).filter((m) => m && m.id); }
  catch (e) { return []; }
};
const inbox = grab('Read Outlook inbox');
const junk = grab('Read Outlook junk');

const tally = {};
const samples = [];
const bump = (k) => { tally[k] = (tally[k] || 0) + 1; };

inbox.forEach((m) => {
  const cls = (m.inferenceClassification || 'focused').toLowerCase();
  const tab = cls === 'other' ? 'Other' : 'Focused';
  bump(tab);
  if (samples.length < 5) samples.push({ tab: tab, subject: m.subject || '(no subject)' });
});
junk.forEach((m) => {
  bump('Junk');
  if (samples.length < 5) samples.push({ tab: 'Junk', subject: m.subject || '(no subject)' });
});

const n = inbox.length + junk.length;
const pctOf = (k) => (n ? Math.round((k / n) * 100) : null);

return [{ json: { _branch: 'outlook', placement: {
  provider: 'Outlook',
  inbox_label: 'Focused', filtered_label: 'Other',
  checked: n, tally: tally,
  inbox_pct: pctOf(tally.Focused || 0), filtered_pct: pctOf(tally.Other || 0), spam_pct: pctOf(tally.Junk || 0),
  samples: samples, skipped: n === 0,
} } }];

// Gather the three branches into one object. The Merge node only exists to
// synchronise them, so each branch is read back by name rather than by position.
const cfg = $('Set config: deliverability').first().json;
const auth = $('Assess authentication').first().json;

const grab = (node) => {
  try {
    const j = $(node).first().json;
    return (j && j.placement) ? j.placement : null;
  } catch (e) { return null; }
};

const providers = [grab('Read Gmail placement'), grab('Read Outlook placement')].filter(Boolean);
const live = providers.filter((p) => !p.skipped);

// Pooled view across whichever mailboxes actually returned mail.
let pooled = null;
if (live.length) {
  const checked = live.reduce((s, p) => s + p.checked, 0);
  const w = (key) => Math.round(live.reduce((s, p) => s + ((p[key] || 0) * p.checked), 0) / checked);
  pooled = { mailboxes: live.length, checked: checked, inbox_pct: w('inbox_pct'), filtered_pct: w('filtered_pct'), spam_pct: w('spam_pct') };
}

return [{ json: Object.assign({}, auth, {
  sender_address: cfg.SENDER_ADDRESS || '',
  providers: providers,
  providers_live: live.length,
  pooled: pooled,
}) }];

// Build the triage prompt. No API call here.
const d = $json;
const notable = d.checks.filter((c) => c.status !== 'pass');

const system = 'You are a deliverability consultant writing for a marketer who sends real campaigns, not a sysadmin. Plain, direct, no jargon without a one-line translation. Never write an em dash, use a comma or a full stop. Only state facts present in the input, never invent a record value or a percentage. Return ONLY valid JSON matching the requested shape, no prose outside it.';

const placementLines = (d.providers || []).map((p) => p.skipped
  ? '- ' + p.provider + ': no mailbox connected, no data.'
  : '- ' + p.provider + ' (' + p.checked + ' messages): ' + p.inbox_pct + '% ' + p.inbox_label +
    ', ' + p.filtered_pct + '% ' + p.filtered_label + ', ' + p.spam_pct + '% spam.').join('\n');

const user = [
  'Domain: ' + d.domain + '. Sending address under test: ' + (d.sender_address || 'not set') + '.',
  'Authentication verdict: ' + d.verdict + '. ' + d.counts.critical + ' critical, ' + d.counts.flags + ' flags, ' + d.counts.passed + ' passed.',
  '',
  'AUTHENTICATION findings that are not passing:',
  notable.length ? notable.map((c) => '- [' + c.status.toUpperCase() + '] ' + c.label + ': ' + c.detail + (c.move ? ' Fix: ' + c.move : '')).join('\n') : '- none, all authentication checks passed.',
  '',
  'DKIM selectors that resolved: ' + (d.dkim_selectors_found.length ? d.dkim_selectors_found.join(', ') : 'none') + ' out of ' + d.dkim_selectors_probed + ' probed.',
  'IMPORTANT: the probe list is a fixed list of selectors used by common ESPs. A selector that did not resolve simply means the domain does not use that provider. It is NOT a broken record, there is nothing in DNS to remove, and it must never be reported as a problem. Only the selectors that resolved exist.',
  '',
  'REAL PLACEMENT, per provider:',
  placementLines || '- no mailboxes connected.',
  d.providers_live ? '' : 'No provider returned data, so say nothing about where mail is landing.',
  '',
  'Write the read. Rank fixes by what actually moves inbox placement, not by how alarming the label sounds. Where providers disagree, say what that implies: a domain-level authentication fault tends to hurt every provider at once, so one provider filtering while another does not usually points at content, sending history, or that provider list rather than at DNS. Say plainly when a placement problem is a content or engagement issue rather than an authentication one.',
  '',
  'Return JSON: {"headline":"one sentence","fixes":[{"rank":1,"what":"","why_it_matters":"","how":""}],"esp_guess":"which ESP the selectors suggest, or empty","provider_read":"one sentence on what the per-provider split implies, or empty if no data","note":"one honest caveat"}',
].join('\n');

const body = { model: 'claude-haiku-4-5', max_tokens: 1500, system: system, messages: [{ role: 'user', content: user }] };
return [{ json: { body: body, _ctx: d } }];

// Assemble the report. Returns it so it shows in the node output and can be
// chained into Slack, Gmail, or a Sheets row.
const ctx = $('Build AI prompt').first().json._ctx;
let ai = {};
try {
  const txt = ($json.content && $json.content[0] && $json.content[0].text) || '{}';
  ai = JSON.parse(txt.replace(/^[^{]*/, '').replace(/[^}]*$/, ''));
} catch (e) { ai = { headline: '', fixes: [], esp_guess: '', provider_read: '', note: '' }; }

const pad = (s, n) => (String(s) + '                    ').slice(0, n);
const L = [];
L.push('EMAIL DELIVERABILITY CHECK  ' + ctx.domain);
L.push('=======================================================================');
L.push('');
L.push('TECHNICAL  ' + ctx.verdict.toUpperCase() + '   (' + ctx.counts.passed + ' passed, ' + ctx.counts.flags + ' flags, ' + ctx.counts.critical + ' critical)');
ctx.checks.forEach((c) => L.push('  [' + c.status + '] ' + c.label + ': ' + c.detail));
L.push('  DKIM selectors found: ' + (ctx.dkim_selectors_found.length ? ctx.dkim_selectors_found.join(', ') : 'none') + ' of ' + ctx.dkim_selectors_probed + ' probed');
if (ai.esp_guess) L.push('  Looks like: ' + ai.esp_guess);
L.push('');
L.push('REAL PLACEMENT   sender: ' + (ctx.sender_address || 'not set'));
L.push('  ' + pad('PROVIDER', 12) + pad('INBOX', 22) + pad('FILTERED', 22) + pad('SPAM', 8) + 'SAMPLE');
(ctx.providers || []).forEach((p) => {
  if (p.skipped) {
    L.push('  ' + pad(p.provider, 12) + 'no mailbox connected');
  } else {
    L.push('  ' + pad(p.provider, 12)
      + pad(p.inbox_pct + '% ' + p.inbox_label, 22)
      + pad(p.filtered_pct + '% ' + p.filtered_label, 22)
      + pad(p.spam_pct + '%', 8)
      + p.checked + ' msgs');
  }
});
if (ctx.pooled) {
  L.push('  ' + pad('POOLED', 12) + pad(ctx.pooled.inbox_pct + '% inbox', 22) + pad(ctx.pooled.filtered_pct + '% filtered', 22) + pad(ctx.pooled.spam_pct + '%', 8) + ctx.pooled.checked + ' msgs across ' + ctx.pooled.mailboxes);
}
if (ai.provider_read) { L.push(''); L.push('  ' + ai.provider_read); }
L.push('');
if (ai.headline) { L.push(ai.headline); L.push(''); }
L.push('FIX IN THIS ORDER');
if ((ai.fixes || []).length) {
  ai.fixes.forEach((f) => {
    L.push('  ' + f.rank + '. ' + f.what);
    if (f.why_it_matters) L.push('     Why: ' + f.why_it_matters);
    if (f.how) L.push('     How: ' + f.how);
  });
} else { L.push('  Nothing outstanding.'); }

(ctx.providers || []).filter((p) => !p.skipped && (p.samples || []).length).forEach((p) => {
  L.push('');
  L.push('RECENT IN ' + p.provider.toUpperCase());
  p.samples.forEach((s) => L.push('  [' + s.tab + '] ' + s.subject));
});
if (ai.note) { L.push(''); L.push('Note: ' + ai.note); }

return [{ json: { report: L.join('\n'), domain: ctx.domain, verdict: ctx.verdict, counts: ctx.counts, checks: ctx.checks, providers: ctx.providers, pooled: ctx.pooled, ai: ai } }];
